
-- ---------- seed: procedures ---------------------------------
insert into public.sim3d_procedures(code,title,programme,category,difficulty,minutes,description,definition,objectives,indications,contraindications,safety,outcomes,refs,scene,steps,unsafe,challenges,exam_seconds,pass_percent,reviewer,position,status)
values ($q$S3D-HH$q$,$q$Hand hygiene with soap and water$q$,$q$ALL$q$,$q$Infection prevention$q$,$q$Basic$q$,5,$q$Wash the hands with soap and water using the full technique.$q$,$q$Cleaning the hands with soap and running water to remove dirt and transient micro-organisms.$q$,array[$q$Prepare before washing$q$,$q$Cover every surface of the hands$q$,$q$Rub for at least 20 seconds$q$,$q$Dry and avoid recontamination$q$]::text[],array[$q$Before and after patient contact$q$,$q$Before aseptic tasks$q$,$q$After body fluid exposure$q$,$q$After removing gloves$q$]::text[],array[$q$None$q$]::text[],array[$q$Remove rings, watches and bracelets first$q$,$q$Keep nails short and clean$q$]::text[],array[$q$Visibly clean hands$q$,$q$Reduced risk of infection$q$]::text[],array[$q$WHO Guidelines on Hand Hygiene in Health Care$q$,$q$Standard nursing fundamentals text (tutor to confirm edition)$q$]::text[],$q${"pose":"supine","positions":[],"zones":[],"pregnant":false,"wound":false,"view":"sink","actions":[{"key":"remove_jewellery","label":"Remove rings, watch and bracelets","group":"technique"},{"key":"wet_hands","label":"Wet hands under running water","group":"technique"},{"key":"apply_soap","label":"Apply soap","group":"technique"},{"key":"rub_palms","label":"Rub palms together","group":"technique"},{"key":"rub_backs","label":"Rub the back of each hand","group":"technique"},{"key":"interlace","label":"Interlace fingers and rub between them","group":"technique"},{"key":"fingertips_thumbs","label":"Rub thumbs and fingertips","group":"technique"},{"key":"rinse","label":"Rinse under running water","group":"technique"},{"key":"dry_towel","label":"Dry with a single-use paper towel","group":"technique"},{"key":"tap_towel","label":"Close the tap with the paper towel","group":"technique"},{"key":"wipe_uniform","label":"Dry hands on your uniform","group":"technique"},{"key":"close_tap_bare","label":"Close the tap with bare wet hands","group":"technique"}],"equipment":["soap_dispenser","hand_rub","towel","gloves_clean","thermometer"]}$q$::jsonb,$q$[{"key":"jewel","title":"Remove jewellery","instruction":"Prepare your hands for washing.","rationale":"Jewellery harbours micro-organisms and prevents effective cleaning.","marks":1,"kind":"object","critical":false,"values":["remove_jewellery"]},{"key":"wet","title":"Wet the hands","instruction":"Start the wash.","rationale":"Water wets the skin so that soap can lather.","marks":1,"kind":"object","critical":false,"values":["wet_hands"],"requires":["jewel"]},{"key":"soap","title":"Apply soap","instruction":"Apply enough soap to cover all surfaces.","rationale":"Soap lifts dirt and organisms from the skin.","marks":1,"kind":"object","critical":false,"values":["apply_soap"],"requires":["wet"]},{"key":"palms","title":"Rub palms","instruction":"Begin the technique.","rationale":"Friction removes organisms.","marks":1,"kind":"object","critical":false,"values":["rub_palms"],"requires":["soap"]},{"key":"backs","title":"Backs of hands","instruction":"Cover each back of hand.","rationale":"These surfaces are often missed.","marks":1,"kind":"object","critical":false,"values":["rub_backs"],"requires":["palms"]},{"key":"between","title":"Between fingers","instruction":"Clean between the fingers.","rationale":"Spaces between the fingers hold organisms.","marks":1,"kind":"object","critical":false,"values":["interlace"],"requires":["backs"]},{"key":"tips","title":"Thumbs and fingertips","instruction":"Clean thumbs and fingertips.","rationale":"Thumbs and fingertips are the most commonly missed areas.","marks":1,"kind":"object","critical":false,"values":["fingertips_thumbs"],"requires":["between"]},{"key":"rinse","title":"Rinse","instruction":"Rinse from wrists to fingertips.","rationale":"Rinsing removes the loosened organisms and soap.","marks":1,"kind":"object","critical":false,"values":["rinse"],"requires":["tips"]},{"key":"dry","title":"Dry","instruction":"Dry thoroughly.","rationale":"Wet skin transfers organisms more easily.","marks":1,"kind":"object","critical":false,"values":["dry_towel"],"requires":["rinse"]},{"key":"tap","title":"Close the tap","instruction":"Avoid recontaminating your hands.","rationale":"A hand-operated tap is contaminated.","marks":1,"kind":"object","critical":false,"values":["tap_towel"],"requires":["dry"]}]$q$::jsonb,$q$[{"kind":"object","value":"wipe_uniform","message":"Drying on your uniform recontaminates your hands.","critical":false,"penalty":1},{"kind":"object","value":"close_tap_bare","message":"Closing a hand-operated tap with bare wet hands recontaminates them.","critical":false,"penalty":1}]$q$::jsonb,$q$[{"id":"hh1","kind":"mistake","title":"Spot the mistakes","scenario":"A nurse wets her hands, rubs for about 5 seconds, rinses, dries on her uniform and closes the tap with bare hands.","prompt":"Which actions are wrong?","multi":true,"options":[{"id":"a","text":"Rubbing for only about 5 seconds","correct":true,"feedback":"Rub for at least 20 seconds."},{"id":"b","text":"Drying on the uniform","correct":true,"feedback":"Use a single-use towel."},{"id":"c","text":"Closing the tap with bare wet hands","correct":true,"feedback":"Use the towel to close a hand-operated tap."},{"id":"d","text":"Wetting hands first","correct":false,"feedback":"This is correct."}],"explanation":"Time, drying and the tap all affect the result."}]$q$::jsonb,600,50,'Owner-approved; tutor review ongoing',0,'published') on conflict (code) do nothing;
insert into public.sim3d_procedures(code,title,programme,category,difficulty,minutes,description,definition,objectives,indications,contraindications,safety,outcomes,refs,scene,steps,unsafe,challenges,exam_seconds,pass_percent,reviewer,position,status)
values ($q$S3D-BP$q$,$q$Blood pressure measurement$q$,$q$ALL$q$,$q$Vital signs$q$,$q$Basic$q$,8,$q$Measure blood pressure with a sphygmomanometer and stethoscope, then interpret the result.$q$,$q$Indirect measurement of arterial pressure in mmHg using a cuff and stethoscope.$q$,array[$q$Prepare the patient and equipment$q$,$q$Use the correct cuff and arm position$q$,$q$Take and record an accurate reading$q$,$q$Recognise a raised reading and act$q$]::text[],array[$q$Routine vital signs$q$,$q$Hypertension monitoring$q$,$q$Antenatal and postnatal checks$q$]::text[],array[$q$Avoid an arm with an IV line, fistula, injury or mastectomy on that side$q$]::text[],array[$q$Patient rested for about 5 minutes$q$,$q$Arm supported at heart level$q$,$q$Do not reinflate repeatedly$q$]::text[],array[$q$Accurate reading recorded$q$,$q$Abnormal value reported$q$]::text[],array[$q$Standard clinical nursing skills text (tutor to confirm edition)$q$,$q$Hypertension guideline in use at your school$q$]::text[],$q${"pose":"sitting","positions":[{"key":"supine","label":"Supine","why":"Lying flat on the back. Used for abdominal examination and many routine procedures."},{"key":"sitting","label":"Sitting upright","why":"Sitting up with the back supported. Used for vital signs and some injections."},{"key":"fowlers","label":"Fowler's","why":"Head of the bed raised to 45 to 60 degrees. Eases breathing."}],"zones":[{"key":"upper_arm_right","label":"Right upper arm (brachial artery)","explain":"The brachial artery runs on the inner side of the upper arm above the elbow crease."},{"key":"upper_arm_left","label":"Left upper arm (brachial artery)","explain":"The brachial artery runs on the inner side of the upper arm above the elbow crease."},{"key":"forearm_right","label":"Right forearm","explain":"The forearm is not the standard site for the cuff."},{"key":"thigh_right","label":"Right thigh","explain":"Thigh readings are used only when arm readings are not possible."}],"pregnant":false,"wound":false,"view":"patient","actions":[{"key":"hand_hygiene","label":"Perform hand hygiene at the sink","group":"care"},{"key":"explain_consent","label":"Introduce yourself, explain and get consent","group":"care"},{"key":"close_curtain","label":"Close the curtain for privacy","group":"care"},{"key":"expose_arm","label":"Expose the arm (remove tight sleeve)","group":"technique"},{"key":"support_arm","label":"Support the arm at heart level","group":"technique"},{"key":"palpate_brachial","label":"Palpate the brachial pulse","group":"technique"},{"key":"inflate_cuff","label":"Inflate the cuff","group":"technique"},{"key":"deflate_slowly","label":"Deflate slowly (2 to 3 mmHg per second)","group":"technique"},{"key":"deflate_fast","label":"Deflate quickly","group":"technique"},{"key":"cuff_over_clothing","label":"Apply the cuff over thick clothing","group":"technique"},{"key":"document","label":"Document the reading","group":"care"}],"equipment":["bp_cuff","stethoscope","alcohol_swab","thermometer","pulse_oximeter","syringe"]}$q$::jsonb,$q$[{"key":"hands","title":"Hand hygiene","instruction":"Decontaminate your hands.","rationale":"Prevents cross-infection.","marks":1,"kind":"object","critical":false,"values":["hand_hygiene"],"hint":{"kind":"sink","value":"sink"}},{"key":"explain","title":"Explain and consent","instruction":"Introduce yourself and explain.","rationale":"Reduces anxiety and gains cooperation.","marks":1,"kind":"object","critical":false,"values":["explain_consent"],"requires":["hands"]},{"key":"equip","title":"Select equipment","instruction":"Choose what you need.","rationale":"Preparation avoids interruption.","marks":3,"kind":"equipment","critical":false,"items":["bp_cuff","stethoscope","alcohol_swab"],"requires":["hands"]},{"key":"position","title":"Position the patient","instruction":"Sit or lie the patient comfortably.","rationale":"Posture affects the reading.","marks":1,"kind":"position","critical":false,"values":["sitting","supine","fowlers"],"requires":["explain"]},{"key":"expose","title":"Expose the arm","instruction":"Remove tight clothing from the arm.","rationale":"Clothing under the cuff alters the reading.","marks":1,"kind":"object","critical":false,"values":["expose_arm"],"requires":["position"]},{"key":"support","title":"Support the arm","instruction":"Arm at heart level.","rationale":"An arm below heart level gives a falsely high reading.","marks":1,"kind":"object","critical":false,"values":["support_arm"],"requires":["expose"]},{"key":"cuff","title":"Apply the cuff","instruction":"Choose the site.","rationale":"The bladder must be over the brachial artery.","marks":2,"kind":"zone","critical":true,"values":["upper_arm_right","upper_arm_left"],"requires":["support","equip"]},{"key":"pulse","title":"Palpate the pulse","instruction":"Find the brachial artery.","rationale":"Locates the stethoscope position.","marks":1,"kind":"object","critical":false,"values":["palpate_brachial"],"requires":["cuff"]},{"key":"inflate","title":"Inflate","instruction":"Inflate above the expected systolic.","rationale":"Occludes the artery.","marks":1,"kind":"object","critical":false,"values":["inflate_cuff"],"requires":["pulse"]},{"key":"deflate","title":"Deflate slowly","instruction":"Release the pressure steadily.","rationale":"Allows accurate reading of the Korotkoff sounds.","marks":1,"kind":"object","critical":true,"values":["deflate_slowly"],"requires":["inflate"]},{"key":"read","title":"Record the reading","instruction":"The sounds begin at 148 and disappear at 94.","rationale":"Systolic is the first sound; diastolic is when sound disappears.","marks":2,"kind":"choice","critical":false,"values":["a"],"requires":["deflate"],"options":[{"id":"a","text":"148/94 mmHg"},{"id":"b","text":"94/148 mmHg"},{"id":"c","text":"120/80 mmHg"},{"id":"d","text":"148/60 mmHg"}],"prompt":"What is the recorded blood pressure?"},{"key":"interpret","title":"Interpret","instruction":"Decide what to do.","rationale":"A raised reading needs a repeat and reporting according to protocol.","marks":2,"kind":"choice","critical":false,"values":["b"],"requires":["read"],"options":[{"id":"a","text":"Ignore it and discharge the patient"},{"id":"b","text":"Let the patient rest, repeat the reading, record both and report according to protocol"},{"id":"c","text":"Give an antihypertensive without a prescription"},{"id":"d","text":"Record nothing until tomorrow"}],"prompt":"This reading is above the usual target for an adult. What is the best next action?"},{"key":"doc","title":"Document","instruction":"Record the reading, arm and position.","rationale":"Accurate records support safe care.","marks":1,"kind":"object","critical":false,"values":["document"],"requires":["read"]}]$q$::jsonb,$q$[{"kind":"object","value":"cuff_over_clothing","message":"A cuff over thick clothing gives an inaccurate reading.","critical":false,"penalty":1},{"kind":"object","value":"deflate_fast","message":"Deflating too quickly can make you miss the true readings.","critical":false,"penalty":1},{"kind":"zone","value":"forearm_right","message":"The upper arm over the brachial artery is the standard site.","critical":false,"penalty":0}]$q$::jsonb,$q$[{"id":"bp1","kind":"mistake","title":"Errors that change the reading","scenario":"A nurse takes a blood pressure straight after the patient walked in, with the arm hanging below heart level and a cuff that is too small.","prompt":"Which errors affect the reading?","multi":true,"options":[{"id":"a","text":"Patient not rested","correct":true,"feedback":"Rest about 5 minutes first."},{"id":"b","text":"Arm below heart level","correct":true,"feedback":"Support at heart level."},{"id":"c","text":"Cuff too small","correct":true,"feedback":"A small cuff reads falsely high."},{"id":"d","text":"Using the brachial artery","correct":false,"feedback":"This is the correct site."}],"explanation":"Rest, position and cuff size all matter."}]$q$::jsonb,600,50,'Owner-approved; tutor review ongoing',1,'published') on conflict (code) do nothing;
insert into public.sim3d_procedures(code,title,programme,category,difficulty,minutes,description,definition,objectives,indications,contraindications,safety,outcomes,refs,scene,steps,unsafe,challenges,exam_seconds,pass_percent,reviewer,position,status)
values ($q$S3D-IM$q$,$q$Intramuscular injection$q$,$q$RN$q$,$q$Medication administration$q$,$q$Intermediate$q$,10,$q$Give an intramuscular injection safely, choosing the right equipment and site.$q$,$q$Giving a drug into a large muscle using a needle and syringe.$q$,array[$q$Check the order$q$,$q$Prepare the equipment$q$,$q$Select the safe site$q$,$q$Inject and dispose safely$q$]::text[],array[$q$Medicines ordered by the IM route$q$,$q$Patient cannot take oral medicine$q$]::text[],array[$q$Bleeding disorders$q$,$q$Infection or injury at the site$q$,$q$Poor muscle mass at the site$q$]::text[],array[$q$Do not recap needles$q$,$q$Use the sharps box at the point of use$q$,$q$Check the five rights$q$]::text[],array[$q$Drug given at the correct site$q$,$q$No needle-stick injury$q$,$q$Record made$q$]::text[],array[$q$Standard nursing procedures manual (tutor to confirm edition)$q$,$q$WHO best practices for injections and related procedures$q$]::text[],$q${"pose":"supine","positions":[{"key":"supine","label":"Supine","why":"Lying flat on the back. Used for abdominal examination and many routine procedures."},{"key":"prone","label":"Prone","why":"Lying face down. Used for back care and some injections."},{"key":"lateral","label":"Left lateral","why":"Lying on the left side. Gives access to the buttock and hip."},{"key":"sitting","label":"Sitting upright","why":"Sitting up with the back supported. Used for vital signs and some injections."}],"zones":[{"key":"deltoid_right","label":"Right deltoid","explain":"Upper arm muscle. Suitable only for small volumes."},{"key":"deltoid_left","label":"Left deltoid","explain":"Upper arm muscle. Suitable only for small volumes."},{"key":"ventrogluteal_right","label":"Right ventrogluteal","explain":"Side of the hip, away from major nerves and vessels."},{"key":"ventrogluteal_left","label":"Left ventrogluteal","explain":"Side of the hip, away from major nerves and vessels."},{"key":"dorsogluteal_right","label":"Right dorsogluteal","explain":"Upper outer buttock. Sciatic nerve injury is a risk."},{"key":"dorsogluteal_left","label":"Left dorsogluteal","explain":"Upper outer buttock. Sciatic nerve injury is a risk."},{"key":"vastus_right","label":"Right vastus lateralis","explain":"Outer middle thigh muscle."},{"key":"vastus_left","label":"Left vastus lateralis","explain":"Outer middle thigh muscle."},{"key":"abdomen","label":"Abdomen","explain":"Not an intramuscular site."}],"pregnant":false,"wound":false,"view":"patient","actions":[{"key":"hand_hygiene","label":"Perform hand hygiene at the sink","group":"care"},{"key":"explain_consent","label":"Introduce yourself, explain and get consent","group":"care"},{"key":"close_curtain","label":"Close the curtain for privacy","group":"care"},{"key":"check_prescription","label":"Check the prescription (five rights)","group":"care"},{"key":"cover_patient","label":"Cover the patient and make comfortable","group":"care"},{"key":"document","label":"Document the procedure","group":"care"},{"key":"swab_skin","label":"Clean the skin with an alcohol swab and let it dry","group":"technique"},{"key":"inject_90","label":"Insert the needle at 90 degrees and inject slowly","group":"technique"},{"key":"recap_needle","label":"Recap the needle","group":"technique"},{"key":"sharps_bin","label":"Place the needle in the sharps box","group":"technique"},{"key":"expose_site","label":"Expose only the site","group":"care"}],"equipment":["syringe","needle","ampoule","alcohol_swab","gloves_clean","sharps_box","kidney_dish","catheter_set","thermometer","dressing_pack"]}$q$::jsonb,$q$[{"key":"hands","title":"Hand hygiene","instruction":"Decontaminate your hands.","rationale":"Reduces cross-infection.","marks":1,"kind":"object","critical":false,"values":["hand_hygiene"],"hint":{"kind":"sink","value":"sink"}},{"key":"check","title":"Check the order","instruction":"Verify the prescription.","rationale":"The five rights prevent medication errors.","marks":2,"kind":"object","critical":true,"values":["check_prescription"],"requires":["hands"]},{"key":"equip","title":"Select equipment","instruction":"Choose what you need for the injection.","rationale":"Preparation prevents interruption and contamination.","marks":4,"kind":"equipment","critical":false,"items":["syringe","needle","ampoule","alcohol_swab","gloves_clean","sharps_box"],"extra_ok":["kidney_dish"],"requires":["check"]},{"key":"explain","title":"Explain and consent","instruction":"Introduce yourself and explain.","rationale":"Consent and cooperation.","marks":1,"kind":"object","critical":false,"values":["explain_consent"],"requires":["equip"]},{"key":"privacy","title":"Privacy","instruction":"Protect the patient's dignity.","rationale":"Respect for privacy.","marks":1,"kind":"object","critical":false,"values":["close_curtain"],"requires":["explain"]},{"key":"position","title":"Position the patient","instruction":"Choose a safe position.","rationale":"The muscle must be relaxed and the site accessible.","marks":1,"kind":"position","critical":false,"values":["lateral","supine"],"requires":["privacy"]},{"key":"site","title":"Choose the site","instruction":"Tap the injection site.","rationale":"The ventrogluteal site avoids major nerves and vessels.","marks":3,"kind":"zone","critical":true,"values":["ventrogluteal_right","ventrogluteal_left"],"requires":["position"]},{"key":"swab","title":"Clean the skin","instruction":"Prepare the skin.","rationale":"Reduces skin organisms.","marks":1,"kind":"object","critical":false,"values":["swab_skin"],"requires":["site"]},{"key":"inject","title":"Inject","instruction":"Give the injection.","rationale":"Correct technique deposits the drug in muscle.","marks":2,"kind":"object","critical":true,"values":["inject_90"],"requires":["swab"]},{"key":"sharps","title":"Dispose of the needle","instruction":"Dispose at the point of use.","rationale":"Prevents needle-stick injury.","marks":2,"kind":"object","critical":true,"values":["sharps_bin"],"requires":["inject"]},{"key":"cover","title":"Make the patient comfortable","instruction":"Cover and tidy.","rationale":"Dignity and comfort.","marks":1,"kind":"object","critical":false,"values":["cover_patient"],"requires":["sharps"]},{"key":"hands2","title":"Hand hygiene","instruction":"Decontaminate your hands again.","rationale":"Removes organisms picked up.","marks":1,"kind":"object","critical":false,"values":["hand_hygiene"],"requires":["sharps"]},{"key":"doc","title":"Document","instruction":"Record the drug, dose, site and time.","rationale":"Accurate records prevent double dosing.","marks":1,"kind":"object","critical":false,"values":["document"],"requires":["hands2"]}]$q$::jsonb,$q$[{"kind":"object","value":"recap_needle","message":"Recapping causes needle-stick injury. Dispose of the needle directly in the sharps box.","critical":true,"penalty":2},{"kind":"zone","value":"dorsogluteal_right","message":"The dorsogluteal site risks sciatic nerve injury.","critical":false,"penalty":1},{"kind":"zone","value":"dorsogluteal_left","message":"The dorsogluteal site risks sciatic nerve injury.","critical":false,"penalty":1},{"kind":"zone","value":"abdomen","message":"The abdomen is not an intramuscular site.","critical":false,"penalty":1}]$q$::jsonb,$q$[{"id":"im1","kind":"mistake","title":"Spot the mistakes","scenario":"A nurse draws up the drug, wipes the skin and injects while the alcohol is still wet, then recaps the needle before disposal.","prompt":"Which actions are mistakes?","multi":true,"options":[{"id":"a","text":"Injecting while the alcohol is wet","correct":true,"feedback":"Let it dry."},{"id":"b","text":"Recapping the needle","correct":true,"feedback":"Dispose directly in the sharps box."},{"id":"c","text":"Wiping the skin","correct":false,"feedback":"Skin cleaning is correct."},{"id":"d","text":"Checking the order first","correct":false,"feedback":"This is correct."}],"explanation":"Two safety errors: wet skin and recapping."},{"id":"im2","kind":"decision","title":"Choosing the site","scenario":"An adult needs an IM injection of 3 mL. The patient is lying on the side.","prompt":"Which site is generally preferred?","multi":false,"options":[{"id":"a","text":"Ventrogluteal","correct":true,"feedback":"Away from major nerves and vessels."},{"id":"b","text":"Upper outer buttock (dorsogluteal)","correct":false,"feedback":"Risk to the sciatic nerve."},{"id":"c","text":"Abdomen","correct":false,"feedback":"Not a muscle site."},{"id":"d","text":"Back of the knee","correct":false,"feedback":"Not safe."}],"explanation":"The ventrogluteal site is commonly preferred."}]$q$::jsonb,600,50,'Owner-approved; tutor review ongoing',2,'published') on conflict (code) do nothing;
insert into public.sim3d_procedures(code,title,programme,category,difficulty,minutes,description,definition,objectives,indications,contraindications,safety,outcomes,refs,scene,steps,unsafe,challenges,exam_seconds,pass_percent,reviewer,position,status)
values ($q$S3D-WD$q$,$q$Aseptic wound dressing$q$,$q$RN$q$,$q$Wound care$q$,$q$Intermediate$q$,12,$q$Clean and dress a wound using an aseptic technique.$q$,$q$Replacing a wound covering using aseptic technique to protect the wound and promote healing.$q$,array[$q$Prepare the equipment and patient$q$,$q$Maintain asepsis$q$,$q$Assess and clean the wound$q$,$q$Dispose and document$q$]::text[],array[$q$Surgical or traumatic wound$q$,$q$Soiled or loosened dressing$q$,$q$Scheduled dressing change$q$]::text[],array[$q$Report suspected deep infection or dehiscence to the doctor$q$]::text[],array[$q$Do not touch the sterile field or wound with bare hands$q$,$q$Dispose of soiled dressings in the clinical waste bag$q$,$q$Hand hygiene before and after$q$]::text[],array[$q$Clean covered wound$q$,$q$No cross-infection$q$,$q$Patient comfortable$q$,$q$Accurate record$q$]::text[],array[$q$Standard nursing procedures manual (tutor to confirm edition)$q$,$q$Wound care guideline in use at your school$q$]::text[],$q${"pose":"supine","positions":[{"key":"supine","label":"Supine","why":"Lying flat on the back. Used for abdominal examination and many routine procedures."},{"key":"sitting","label":"Sitting upright","why":"Sitting up with the back supported. Used for vital signs and some injections."},{"key":"fowlers","label":"Fowler's","why":"Head of the bed raised to 45 to 60 degrees. Eases breathing."}],"zones":[{"key":"wound","label":"Wound on the left lower leg","explain":"The wound site to be cleaned and dressed."},{"key":"leg_right","label":"Right lower leg","explain":"Healthy skin."},{"key":"abdomen","label":"Abdomen","explain":"Not relevant to this wound."}],"pregnant":false,"wound":true,"view":"patient","actions":[{"key":"hand_hygiene","label":"Perform hand hygiene at the sink","group":"care"},{"key":"explain_consent","label":"Introduce yourself, explain and get consent","group":"care"},{"key":"close_curtain","label":"Close the curtain for privacy","group":"care"},{"key":"check_prescription","label":"Check the prescription (five rights)","group":"care"},{"key":"cover_patient","label":"Cover the patient and make comfortable","group":"care"},{"key":"document","label":"Document the procedure","group":"care"},{"key":"expose_wound","label":"Expose only the wound area","group":"care"},{"key":"open_pack","label":"Open the dressing pack without touching the inside","group":"technique"},{"key":"remove_old","label":"Remove the old dressing with clean gloves and discard it","group":"technique"},{"key":"assess_wound","label":"Assess the wound (size, colour, drainage, odour)","group":"technique"},{"key":"clean_in_out","label":"Clean from the cleanest area outwards, one swab per stroke","group":"technique"},{"key":"clean_back_forth","label":"Clean back and forth with the same swab","group":"technique"},{"key":"dry_wound","label":"Pat the area dry","group":"technique"},{"key":"apply_dressing","label":"Apply the sterile dressing and secure it","group":"technique"},{"key":"dispose_waste","label":"Dispose of waste in the clinical waste bag","group":"technique"},{"key":"touch_sterile","label":"Touch the sterile field with bare hands","group":"technique"}],"equipment":["dressing_pack","gloves_sterile","gloves_clean","saline","tape","waste_bag","hand_rub","kidney_dish","sharps_box","thermometer","clean_cloth"]}$q$::jsonb,$q$[{"key":"hands","title":"Hand hygiene","instruction":"Decontaminate your hands.","rationale":"Reduces infection.","marks":1,"kind":"object","critical":false,"values":["hand_hygiene"],"hint":{"kind":"sink","value":"sink"}},{"key":"equip","title":"Select equipment","instruction":"Choose what you need.","rationale":"Complete preparation before opening anything sterile.","marks":4,"kind":"equipment","critical":false,"items":["dressing_pack","gloves_sterile","saline","tape","waste_bag","gloves_clean"],"extra_ok":["hand_rub","kidney_dish","clean_cloth"],"requires":["hands"]},{"key":"explain","title":"Explain and consent","instruction":"Explain the procedure.","rationale":"Consent and cooperation.","marks":1,"kind":"object","critical":false,"values":["explain_consent"],"requires":["equip"]},{"key":"privacy","title":"Privacy","instruction":"Protect dignity.","rationale":"Respect for privacy.","marks":1,"kind":"object","critical":false,"values":["close_curtain"],"requires":["explain"]},{"key":"position","title":"Position","instruction":"Position comfortably with the wound accessible.","rationale":"Allows access without strain.","marks":1,"kind":"position","critical":false,"values":["supine","sitting","fowlers"],"requires":["privacy"]},{"key":"expose","title":"Expose the wound only","instruction":"Keep the rest covered.","rationale":"Dignity and warmth.","marks":1,"kind":"object","critical":false,"values":["expose_wound"],"requires":["position"]},{"key":"open","title":"Open the pack aseptically","instruction":"Create the sterile field.","rationale":"Do not touch the inside.","marks":2,"kind":"object","critical":true,"values":["open_pack"],"requires":["expose"]},{"key":"remove","title":"Remove the old dressing","instruction":"Wear clean gloves.","rationale":"Protects you from body fluids.","marks":1,"kind":"object","critical":false,"values":["remove_old"],"requires":["open"]},{"key":"assess","title":"Assess the wound","instruction":"Observe and note.","rationale":"Detects infection or poor healing.","marks":2,"kind":"object","critical":false,"values":["assess_wound"],"requires":["remove"]},{"key":"clean","title":"Clean the wound","instruction":"Choose the technique.","rationale":"Cleaning direction prevents contamination of the wound.","marks":3,"kind":"object","critical":true,"values":["clean_in_out"],"requires":["assess"]},{"key":"dry","title":"Dry","instruction":"Pat dry.","rationale":"A moist surface favours bacteria.","marks":1,"kind":"object","critical":false,"values":["dry_wound"],"requires":["clean"]},{"key":"dress","title":"Apply the dressing","instruction":"Cover and secure.","rationale":"Protects the wound.","marks":2,"kind":"object","critical":false,"values":["apply_dressing"],"requires":["dry"]},{"key":"waste","title":"Dispose of waste","instruction":"Use the clinical waste bag.","rationale":"Prevents contamination of the environment.","marks":1,"kind":"object","critical":false,"values":["dispose_waste"],"requires":["dress"]},{"key":"hands2","title":"Hand hygiene","instruction":"Decontaminate again.","rationale":"Removes organisms.","marks":1,"kind":"object","critical":false,"values":["hand_hygiene"],"requires":["waste"]},{"key":"doc","title":"Document","instruction":"Record the findings and care.","rationale":"Continuity of care.","marks":1,"kind":"object","critical":false,"values":["document"],"requires":["hands2"]}]$q$::jsonb,$q$[{"kind":"object","value":"clean_back_forth","message":"Using one swab back and forth spreads organisms.","critical":false,"penalty":1},{"kind":"object","value":"touch_sterile","message":"Touching the sterile field breaks asepsis.","critical":true,"penalty":2}]$q$::jsonb,$q$[{"id":"wd1","kind":"decision","title":"Cleaning direction","scenario":"You are cleaning a clean surgical wound.","prompt":"How should you clean it?","multi":false,"options":[{"id":"a","text":"From the cleanest area outwards, using a new swab for each stroke","correct":true,"feedback":"Prevents spreading organisms."},{"id":"b","text":"Back and forth with one swab","correct":false,"feedback":"Spreads organisms."},{"id":"c","text":"From the dirtiest area into the wound","correct":false,"feedback":"Contaminates the wound."},{"id":"d","text":"Scrubbing hard","correct":false,"feedback":"Damages tissue."}],"explanation":"Clean to dirty."}]$q$::jsonb,600,50,'Owner-approved; tutor review ongoing',3,'published') on conflict (code) do nothing;
insert into public.sim3d_procedures(code,title,programme,category,difficulty,minutes,description,definition,objectives,indications,contraindications,safety,outcomes,refs,scene,steps,unsafe,challenges,exam_seconds,pass_percent,reviewer,position,status)
values ($q$S3D-UC$q$,$q$Urinary catheterisation (female)$q$,$q$RN$q$,$q$Elimination$q$,$q$Advanced$q$,15,$q$Insert an indwelling urinary catheter aseptically.$q$,$q$Passing a sterile catheter through the urethra into the bladder using aseptic technique.$q$,array[$q$Explain and protect privacy$q$,$q$Maintain asepsis$q$,$q$Insert to the correct depth$q$,$q$Secure and document$q$]::text[],array[$q$Urinary retention$q$,$q$Strict fluid output monitoring$q$,$q$Before some surgeries$q$]::text[],array[$q$Suspected urethral injury$q$,$q$Active urethral infection unless ordered$q$]::text[],array[$q$Never force the catheter$q$,$q$Inflate the balloon only after urine flows$q$,$q$Keep the drainage bag below the bladder$q$]::text[],array[$q$Urine drains freely$q$,$q$No infection introduced$q$,$q$Catheter secured$q$]::text[],array[$q$Standard nursing procedures manual (tutor to confirm edition)$q$,$q$Catheter-associated infection prevention guideline in use at your school$q$]::text[],$q${"pose":"dorsal_recumbent","positions":[{"key":"supine","label":"Supine","why":"Lying flat on the back. Used for abdominal examination and many routine procedures."},{"key":"lateral","label":"Left lateral","why":"Lying on the left side. Gives access to the buttock and hip."},{"key":"dorsal_recumbent","label":"Dorsal recumbent","why":"On the back with knees bent and feet flat. Used for catheterisation and perineal care."},{"key":"lithotomy","label":"Lithotomy","why":"On the back with the hips and knees flexed and the legs supported. Used for delivery."}],"zones":[{"key":"meatus","label":"Urethral meatus","explain":"The opening of the urethra, above the vagina and below the clitoris."},{"key":"vaginal_opening","label":"Vaginal opening","explain":"Not the entry for the catheter."},{"key":"thigh_right","label":"Right thigh","explain":"Used to secure the catheter bag tube."}],"pregnant":false,"wound":false,"view":"patient","actions":[{"key":"hand_hygiene","label":"Perform hand hygiene at the sink","group":"care"},{"key":"explain_consent","label":"Introduce yourself, explain and get consent","group":"care"},{"key":"close_curtain","label":"Close the curtain for privacy","group":"care"},{"key":"check_prescription","label":"Check the prescription (five rights)","group":"care"},{"key":"cover_patient","label":"Cover the patient and make comfortable","group":"care"},{"key":"document","label":"Document the procedure","group":"care"},{"key":"expose_perineum","label":"Expose the perineum, keeping the patient covered","group":"care"},{"key":"open_set","label":"Open the sterile set without contamination","group":"technique"},{"key":"don_sterile","label":"Put on sterile gloves","group":"technique"},{"key":"place_drape","label":"Place the sterile drape","group":"technique"},{"key":"clean_meatus","label":"Clean the meatus front to back","group":"technique"},{"key":"clean_back_front","label":"Clean back to front","group":"technique"},{"key":"lubricate_insert","label":"Lubricate and insert the catheter gently","group":"technique"},{"key":"force_catheter","label":"Push the catheter in with force","group":"technique"},{"key":"confirm_urine","label":"Confirm that urine flows","group":"technique"},{"key":"inflate_balloon","label":"Inflate the balloon","group":"technique"},{"key":"secure_bag","label":"Secure the catheter and hang the bag below the bladder","group":"technique"}],"equipment":["catheter_set","gloves_sterile","antiseptic","lubricant","drape","kidney_dish","hand_rub","waste_bag","thermometer","iv_cannula"]}$q$::jsonb,$q$[{"key":"hands","title":"Hand hygiene","instruction":"Decontaminate your hands.","rationale":"Reduces infection.","marks":1,"kind":"object","critical":false,"values":["hand_hygiene"],"hint":{"kind":"sink","value":"sink"}},{"key":"check","title":"Check the order","instruction":"Confirm catheterisation is ordered and why.","rationale":"Avoids unnecessary catheterisation.","marks":1,"kind":"object","critical":false,"values":["check_prescription"],"requires":["hands"]},{"key":"equip","title":"Select equipment","instruction":"Choose what you need.","rationale":"Complete preparation first.","marks":5,"kind":"equipment","critical":false,"items":["catheter_set","gloves_sterile","antiseptic","lubricant","drape"],"extra_ok":["kidney_dish","hand_rub","waste_bag"],"requires":["check"]},{"key":"explain","title":"Explain and consent","instruction":"Explain the procedure.","rationale":"Consent and cooperation.","marks":1,"kind":"object","critical":false,"values":["explain_consent"],"requires":["equip"]},{"key":"privacy","title":"Privacy","instruction":"Protect dignity.","rationale":"Respect for privacy.","marks":1,"kind":"object","critical":false,"values":["close_curtain"],"requires":["explain"]},{"key":"position","title":"Position","instruction":"Choose the position.","rationale":"Exposes the meatus clearly.","marks":2,"kind":"position","critical":false,"values":["dorsal_recumbent"],"requires":["privacy"]},{"key":"expose","title":"Expose the perineum","instruction":"Keep the rest covered.","rationale":"Dignity.","marks":1,"kind":"object","critical":false,"values":["expose_perineum"],"requires":["position"]},{"key":"open","title":"Open the sterile set","instruction":"Maintain the sterile field.","rationale":"Asepsis.","marks":2,"kind":"object","critical":true,"values":["open_set"],"requires":["expose"]},{"key":"gloves","title":"Put on sterile gloves","instruction":"Use the correct technique.","rationale":"Prevents contamination.","marks":2,"kind":"object","critical":true,"values":["don_sterile"],"requires":["open"]},{"key":"drape","title":"Place the drape","instruction":"Create the sterile field.","rationale":"Asepsis.","marks":1,"kind":"object","critical":false,"values":["place_drape"],"requires":["gloves"]},{"key":"clean","title":"Clean the meatus","instruction":"Choose the direction.","rationale":"Front to back prevents bringing faecal organisms to the urethra.","marks":3,"kind":"object","critical":true,"values":["clean_meatus"],"requires":["drape"]},{"key":"insert","title":"Insert gently","instruction":"Lubricate and insert.","rationale":"Gentle insertion reduces trauma.","marks":3,"kind":"object","critical":true,"values":["lubricate_insert"],"requires":["clean"]},{"key":"urine","title":"Confirm urine flow","instruction":"Watch for urine.","rationale":"Urine confirms the tip is in the bladder.","marks":2,"kind":"object","critical":false,"values":["confirm_urine"],"requires":["insert"]},{"key":"balloon","title":"Inflate the balloon","instruction":"Only after urine flows.","rationale":"Inflating in the urethra causes injury.","marks":3,"kind":"object","critical":true,"values":["inflate_balloon"],"requires":["urine"]},{"key":"secure","title":"Secure and position the bag","instruction":"Below bladder level.","rationale":"Prevents backflow and infection.","marks":2,"kind":"object","critical":false,"values":["secure_bag"],"requires":["balloon"]},{"key":"hands2","title":"Hand hygiene and comfort","instruction":"Cover the patient and wash.","rationale":"Dignity and infection control.","marks":1,"kind":"object","critical":false,"values":["cover_patient"],"requires":["secure"]},{"key":"doc","title":"Document","instruction":"Record size, time, volume and urine.","rationale":"Continuity of care.","marks":1,"kind":"object","critical":false,"values":["document"],"requires":["hands2"]}]$q$::jsonb,$q$[{"kind":"object","value":"clean_back_front","message":"Cleaning back to front moves organisms toward the urethra.","critical":false,"penalty":1},{"kind":"object","value":"force_catheter","message":"Never force a catheter. This can injure the urethra.","critical":true,"penalty":2}]$q$::jsonb,$q$[{"id":"uc1","kind":"decision","title":"No urine drains","scenario":"After inserting the catheter to the full length, no urine comes out.","prompt":"What should you do?","multi":false,"options":[{"id":"a","text":"Do not inflate the balloon; check the position and ask the patient to cough or breathe deeply, then reassess","correct":true,"feedback":"The balloon stays deflated until urine flows."},{"id":"b","text":"Inflate the balloon to hold it in place","correct":false,"feedback":"Risk of urethral injury."},{"id":"c","text":"Push in harder","correct":false,"feedback":"Never force."},{"id":"d","text":"Leave and report nothing","correct":false,"feedback":"Always report and document."}],"explanation":"Confirm position before inflating."}]$q$::jsonb,600,50,'Owner-approved; tutor review ongoing',4,'published') on conflict (code) do nothing;
insert into public.sim3d_procedures(code,title,programme,category,difficulty,minutes,description,definition,objectives,indications,contraindications,safety,outcomes,refs,scene,steps,unsafe,challenges,exam_seconds,pass_percent,reviewer,position,status)
values ($q$S3D-LM$q$,$q$Abdominal examination in pregnancy (Leopold manoeuvres)$q$,$q$RM$q$,$q$Antenatal care$q$,$q$Intermediate$q$,12,$q$Palpate the pregnant abdomen to find lie, presentation, position and descent.$q$,$q$A systematic abdominal palpation in four steps to assess the fetus.$q$,array[$q$Prepare the woman$q$,$q$Perform the four grips$q$,$q$Interpret findings$q$,$q$Record and refer if abnormal$q$]::text[],array[$q$Antenatal visits after about 28 weeks$q$,$q$On admission in labour$q$]::text[],array[$q$Suspected placenta praevia with bleeding: do not palpate vigorously and refer$q$]::text[],array[$q$Warm hands, gentle pressure$q$,$q$Woman has emptied her bladder$q$,$q$Stop and refer for pain or bleeding$q$]::text[],array[$q$Lie and presentation recorded$q$,$q$Referral if abnormal$q$]::text[],array[$q$Standard midwifery text (tutor to confirm edition)$q$,$q$Antenatal care guideline in use at your school$q$]::text[],$q${"pose":"supine","positions":[{"key":"supine","label":"Supine","why":"Lying flat on the back. Used for abdominal examination and many routine procedures."},{"key":"lateral","label":"Left lateral","why":"Lying on the left side. Gives access to the buttock and hip."},{"key":"fowlers","label":"Fowler's","why":"Head of the bed raised to 45 to 60 degrees. Eases breathing."},{"key":"dorsal_recumbent","label":"Dorsal recumbent","why":"On the back with knees bent and feet flat. Used for catheterisation and perineal care."}],"zones":[{"key":"fundus","label":"Fundus","explain":"The top of the uterus. First grip: which fetal part is here."},{"key":"lateral_right","label":"Right side of the uterus","explain":"Second grip: feel for the back and small parts."},{"key":"lateral_left","label":"Left side of the uterus","explain":"Second grip: feel for the back and small parts."},{"key":"suprapubic","label":"Above the symphysis pubis","explain":"Third grip: the presenting part."},{"key":"pelvic_brim","label":"Pelvic brim","explain":"Fourth grip: descent of the presenting part into the pelvis."},{"key":"epigastrium","label":"Upper abdomen","explain":"Not a Leopold grip position."}],"pregnant":true,"wound":false,"view":"patient","actions":[{"key":"hand_hygiene","label":"Perform hand hygiene at the sink","group":"care"},{"key":"explain_consent","label":"Introduce yourself, explain and get consent","group":"care"},{"key":"close_curtain","label":"Close the curtain for privacy","group":"care"},{"key":"empty_bladder","label":"Ask the woman to empty her bladder","group":"care"},{"key":"warm_hands","label":"Warm your hands","group":"care"},{"key":"face_head","label":"Face the woman's head (first and second grips)","group":"technique"},{"key":"face_feet","label":"Face the woman's feet (third and fourth grips)","group":"technique"},{"key":"press_deep","label":"Press deeply and quickly","group":"technique"},{"key":"listen_fhr","label":"Listen to the fetal heart with the Pinard","group":"technique"},{"key":"cover_patient","label":"Cover the woman and make her comfortable","group":"care"},{"key":"document","label":"Document the findings","group":"care"}],"equipment":["pinard","tape_measure","gloves_clean","thermometer","hand_rub","bp_cuff","syringe"]}$q$::jsonb,$q$[{"key":"hands","title":"Hand hygiene","instruction":"Decontaminate your hands.","rationale":"Reduces infection.","marks":1,"kind":"object","critical":false,"values":["hand_hygiene"],"hint":{"kind":"sink","value":"sink"}},{"key":"explain","title":"Explain and consent","instruction":"Introduce yourself and explain.","rationale":"Consent and cooperation.","marks":1,"kind":"object","critical":false,"values":["explain_consent"],"requires":["hands"]},{"key":"bladder","title":"Empty the bladder","instruction":"Ask the woman to void.","rationale":"A full bladder is uncomfortable and distorts findings.","marks":1,"kind":"object","critical":false,"values":["empty_bladder"],"requires":["explain"]},{"key":"equip","title":"Select equipment","instruction":"Choose what you need.","rationale":"Preparation.","marks":2,"kind":"equipment","critical":false,"items":["pinard","tape_measure"],"extra_ok":["gloves_clean","hand_rub"],"requires":["bladder"]},{"key":"privacy","title":"Privacy","instruction":"Protect dignity.","rationale":"Respect for privacy.","marks":1,"kind":"object","critical":false,"values":["close_curtain"],"requires":["equip"]},{"key":"position","title":"Position","instruction":"Choose a position.","rationale":"Comfort and relaxed abdominal muscles.","marks":2,"kind":"position","critical":false,"values":["supine","dorsal_recumbent"],"requires":["privacy"]},{"key":"warm","title":"Warm your hands","instruction":"Before touching.","rationale":"Cold hands tense the abdominal muscles.","marks":1,"kind":"object","critical":false,"values":["warm_hands"],"requires":["position"]},{"key":"fundal","title":"First grip: fundus","instruction":"Tap the first grip area.","rationale":"Identifies which fetal pole is in the fundus.","marks":2,"kind":"zone","critical":false,"values":["fundus"],"requires":["warm"]},{"key":"lateral","title":"Second grip: sides","instruction":"Tap the second grip area.","rationale":"Finds the back and small parts.","marks":2,"kind":"zone","critical":false,"values":["lateral_right","lateral_left"],"requires":["fundal"]},{"key":"pelvic1","title":"Third grip: presenting part","instruction":"Tap the third grip area.","rationale":"Identifies what is presenting.","marks":2,"kind":"zone","critical":false,"values":["suprapubic"],"requires":["lateral"]},{"key":"pelvic2","title":"Fourth grip: descent","instruction":"Tap the fourth grip area.","rationale":"Assesses engagement.","marks":2,"kind":"zone","critical":false,"values":["pelvic_brim"],"requires":["pelvic1"]},{"key":"lie","title":"Interpret the lie","instruction":"The long axis of the fetus is parallel to the mother's spine, with a firm round head felt low.","rationale":"A longitudinal lie with cephalic presentation is expected at term.","marks":2,"kind":"choice","critical":false,"values":["a"],"requires":["pelvic2"],"options":[{"id":"a","text":"Longitudinal lie, cephalic presentation"},{"id":"b","text":"Transverse lie"},{"id":"c","text":"Breech presentation"},{"id":"d","text":"Oblique lie"}],"prompt":"What does this indicate?"},{"key":"cover","title":"Make her comfortable","instruction":"Cover and help up.","rationale":"Dignity.","marks":1,"kind":"object","critical":false,"values":["cover_patient"],"requires":["lie"]},{"key":"doc","title":"Document","instruction":"Record lie, presentation and engagement.","rationale":"Continuity of care.","marks":1,"kind":"object","critical":false,"values":["document"],"requires":["lie"]}]$q$::jsonb,$q$[{"kind":"object","value":"press_deep","message":"Deep, rapid pressure is uncomfortable and may harm the fetus.","critical":false,"penalty":1}]$q$::jsonb,$q$[{"id":"lm1","kind":"decision","title":"Abnormal finding","scenario":"On palpation a firm round part is found in the fundus and a softer irregular part in the pelvis at 38 weeks.","prompt":"What is the best action?","multi":false,"options":[{"id":"a","text":"Record a possible breech presentation and refer according to protocol","correct":true,"feedback":"Report and refer."},{"id":"b","text":"Record cephalic and reassure","correct":false,"feedback":"Findings suggest breech."},{"id":"c","text":"Attempt to turn the baby","correct":false,"feedback":"Not a midwife's decision without protocol."},{"id":"d","text":"Do nothing","correct":false,"feedback":"Always report."}],"explanation":"Abnormal lie or presentation near term needs referral."}]$q$::jsonb,600,50,'Owner-approved; tutor review ongoing',5,'published') on conflict (code) do nothing;
insert into public.sim3d_procedures(code,title,programme,category,difficulty,minutes,description,definition,objectives,indications,contraindications,safety,outcomes,refs,scene,steps,unsafe,challenges,exam_seconds,pass_percent,reviewer,position,status)
values ($q$S3D-AM$q$,$q$Active management of the third stage of labour$q$,$q$RM$q$,$q$Labour and delivery$q$,$q$Advanced$q$,12,$q$Reduce postpartum haemorrhage with an oxytocic, controlled cord traction and uterine massage.$q$,$q$A set of interventions in the third stage to prevent postpartum haemorrhage.$q$,array[$q$Give oxytocin promptly$q$,$q$Deliver the placenta safely$q$,$q$Examine the placenta$q$,$q$Massage the uterus and monitor$q$]::text[],array[$q$All vaginal births in the facility$q$]::text[],array[$q$Undiagnosed second baby: do not give oxytocin until excluded$q$]::text[],array[$q$Rule out another baby before oxytocin$q$,$q$Never pull the cord without counter-traction$q$,$q$Watch for signs of uterine inversion$q$]::text[],array[$q$Placenta delivered complete$q$,$q$Uterus firm$q$,$q$Blood loss minimal$q$]::text[],array[$q$WHO recommendations for the prevention and treatment of postpartum haemorrhage$q$,$q$Standard midwifery text (tutor to confirm edition)$q$]::text[],$q${"pose":"lithotomy","positions":[{"key":"supine","label":"Supine","why":"Lying flat on the back. Used for abdominal examination and many routine procedures."},{"key":"dorsal_recumbent","label":"Dorsal recumbent","why":"On the back with knees bent and feet flat. Used for catheterisation and perineal care."},{"key":"lithotomy","label":"Lithotomy","why":"On the back with the hips and knees flexed and the legs supported. Used for delivery."}],"zones":[{"key":"thigh_right","label":"Right outer thigh","explain":"Intramuscular injection site for oxytocin."},{"key":"thigh_left","label":"Left outer thigh","explain":"Intramuscular injection site for oxytocin."},{"key":"uterus_fundus","label":"Uterine fundus","explain":"Where the uterus is palpated and massaged."},{"key":"abdomen_upper","label":"Upper abdomen","explain":"Not the uterine fundus."}],"pregnant":false,"wound":false,"view":"patient","actions":[{"key":"hand_hygiene","label":"Perform hand hygiene at the sink","group":"care"},{"key":"explain_consent","label":"Explain what you are doing to the mother","group":"care"},{"key":"palpate_second_baby","label":"Palpate the abdomen to exclude another baby","group":"technique"},{"key":"clamp_cord","label":"Clamp the cord","group":"technique"},{"key":"cct_counter","label":"Controlled cord traction with counter-traction on the uterus","group":"technique"},{"key":"pull_cord","label":"Pull the cord hard without supporting the uterus","group":"technique"},{"key":"deliver_placenta","label":"Deliver the placenta and membranes","group":"technique"},{"key":"check_placenta","label":"Examine the placenta and membranes for completeness","group":"technique"},{"key":"massage_uterus","label":"Massage the uterus until firm","group":"technique"},{"key":"monitor_bleeding","label":"Monitor bleeding, pulse and uterine tone","group":"technique"},{"key":"sharps_bin","label":"Place the needle in the sharps box","group":"technique"},{"key":"document","label":"Document the third stage","group":"care"}],"equipment":["oxytocin","syringe","needle","cord_clamp","scissors","gloves_sterile","kidney_dish","alcohol_swab","sharps_box","iv_cannula","thermometer"]}$q$::jsonb,$q$[{"key":"hands","title":"Hand hygiene and gloves","instruction":"Decontaminate your hands.","rationale":"Reduces infection.","marks":1,"kind":"object","critical":false,"values":["hand_hygiene"],"hint":{"kind":"sink","value":"sink"}},{"key":"equip","title":"Select equipment","instruction":"Choose what you need.","rationale":"Be ready within the first minute.","marks":4,"kind":"equipment","critical":false,"items":["oxytocin","syringe","needle","cord_clamp","scissors","gloves_sterile"],"extra_ok":["kidney_dish","alcohol_swab","sharps_box"],"requires":["hands"]},{"key":"second","title":"Exclude another baby","instruction":"Check before oxytocin.","rationale":"Oxytocin with a second baby in the uterus is dangerous.","marks":3,"kind":"object","critical":true,"values":["palpate_second_baby"],"requires":["equip"]},{"key":"oxy","title":"Give oxytocin 10 IU IM","instruction":"Choose the site.","rationale":"Contracts the uterus and reduces bleeding.","marks":3,"kind":"zone","critical":true,"values":["thigh_right","thigh_left"],"requires":["second"]},{"key":"clamp","title":"Clamp the cord","instruction":"Clamp near the baby.","rationale":"Separates the baby from the placenta.","marks":1,"kind":"object","critical":false,"values":["clamp_cord"],"requires":["oxy"]},{"key":"cct","title":"Controlled cord traction","instruction":"Apply with counter-traction.","rationale":"Counter-traction prevents uterine inversion.","marks":3,"kind":"object","critical":true,"values":["cct_counter"],"requires":["clamp"]},{"key":"deliver","title":"Deliver the placenta","instruction":"Support and guide it out.","rationale":"Complete delivery of the placenta and membranes.","marks":1,"kind":"object","critical":false,"values":["deliver_placenta"],"requires":["cct"]},{"key":"check","title":"Examine the placenta","instruction":"Check it is complete.","rationale":"Retained tissue causes bleeding.","marks":2,"kind":"object","critical":false,"values":["check_placenta"],"requires":["deliver"]},{"key":"massage","title":"Massage the uterus","instruction":"Until firm.","rationale":"A contracted uterus controls bleeding.","marks":2,"kind":"object","critical":false,"values":["massage_uterus"],"requires":["check"]},{"key":"monitor","title":"Monitor","instruction":"Bleeding, pulse and uterine tone.","rationale":"Early detection of haemorrhage.","marks":1,"kind":"object","critical":false,"values":["monitor_bleeding"],"requires":["massage"]},{"key":"sharps","title":"Dispose of the needle","instruction":"Sharps box.","rationale":"Prevents needle-stick injury.","marks":1,"kind":"object","critical":false,"values":["sharps_bin"],"requires":["oxy"]},{"key":"doc","title":"Document","instruction":"Record the third stage and blood loss.","rationale":"Continuity of care.","marks":1,"kind":"object","critical":false,"values":["document"],"requires":["monitor"]}]$q$::jsonb,$q$[{"kind":"object","value":"pull_cord","message":"Never pull on the cord without counter-traction. This risks uterine inversion.","critical":true,"penalty":3}]$q$::jsonb,$q$[{"id":"am1","kind":"decision","title":"Before oxytocin","scenario":"The baby has just been born. You are about to give oxytocin.","prompt":"What must you do first?","multi":false,"options":[{"id":"a","text":"Palpate the abdomen to exclude another baby","correct":true,"feedback":"A second baby must be excluded first."},{"id":"b","text":"Pull the cord","correct":false,"feedback":"Unsafe."},{"id":"c","text":"Wait one hour","correct":false,"feedback":"Delay increases bleeding."},{"id":"d","text":"Massage hard first","correct":false,"feedback":"Massage follows placenta delivery."}],"explanation":"Always exclude another baby first."}]$q$::jsonb,600,50,'Owner-approved; tutor review ongoing',6,'published') on conflict (code) do nothing;
